window.IL_MODULES['systemd'] = {
  title: "Systemd 服务管理 交互式学习 · 迷你 systemctl 命令台",
  links: ["<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">", "<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>", "<link href=\"https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,400;0,500;0,600;1,400;1,500&family=JetBrains+Mono:wght@400;600&display=swap\" rel=\"stylesheet\">"],
  needsReady: false,
  css: "\n\n  :root {\n    --bg: #0e1117;\n    --card: #151a24;\n    --raise: #1b2230;\n    --border: #242c3c;\n    --line: #2f394d;\n    --text: #e6e9ef;\n    --dim: #99a3b5;\n    --muted: #5c6578;\n    --accent: #d4a853;\n    --sd: #a3e635;\n    --ok: #34d399;\n    --bad: #ef476f;\n    --info: #5aa2ff;\n    --orange: #f0a04b;\n    --mono: 'JetBrains Mono', ui-monospace, SFMono-Regular, Consolas, monospace;\n    --display: 'Cormorant Garamond', Georgia, 'Noto Serif SC', 'Source Han Serif SC', serif;\n    --body: -apple-system, 'PingFang SC', 'Microsoft YaHei', 'Segoe UI', sans-serif;\n  }\n  * { box-sizing: border-box; margin: 0; padding: 0; }\n  body {\n    font-family: var(--body);\n    background: var(--bg);\n    color: var(--text);\n    line-height: 1.7;\n    -webkit-font-smoothing: antialiased;\n  }\n  body::before {\n    content: '';\n    position: fixed; inset: 0;\n    background:\n      radial-gradient(ellipse 70% 45% at 15% -5%, rgba(163,230,53,0.05), transparent),\n      radial-gradient(ellipse 55% 40% at 85% 8%, rgba(212,168,83,0.05), transparent);\n    pointer-events: none; z-index: 0;\n  }\n\n  .mast {\n    position: relative; z-index: 1;\n    max-width: 940px; margin: 0 auto; padding: 40px 24px 8px; text-align: center;\n  }\n  .mast-top { display: flex; justify-content: space-between; align-items: center; margin-bottom: 14px; }\n  .badge {\n    font-size: 10px; font-weight: 700; letter-spacing: 2.5px; text-transform: uppercase;\n    color: var(--accent); padding: 4px 10px; border: 1px solid rgba(212,168,83,0.35);\n    border-radius: 999px; background: rgba(212,168,83,0.08);\n  }\n  .mast-count { font-family: var(--mono); font-size: 12px; color: var(--muted); }\n  .mast h1 {\n    font-family: var(--display); font-size: clamp(34px, 5.5vw, 52px); font-weight: 600;\n    letter-spacing: -0.02em; line-height: 1.1; margin-bottom: 6px;\n  }\n  .mast h1 em { font-style: italic; color: var(--sd); font-weight: 500; }\n  .subtitle { color: var(--dim); font-size: 15px; margin-bottom: 22px; }\n\n  .progress-track {\n    height: 6px; background: var(--raise); border: 1px solid var(--border);\n    border-radius: 999px; overflow: hidden; margin-bottom: 8px;\n  }\n  .progress-fill {\n    height: 100%; width: 0; background: linear-gradient(90deg, var(--sd), var(--accent));\n    border-radius: 999px; transition: width 0.5s ease;\n  }\n  .progress-meta {\n    display: flex; justify-content: center; align-items: center; gap: 14px;\n    font-family: var(--mono); font-size: 12px; color: var(--muted);\n  }\n  .done-badge {\n    font-size: 11px; font-weight: 700; color: var(--ok);\n    border: 1px solid rgba(52,211,153,0.4); border-radius: 999px; padding: 2px 10px;\n    background: rgba(52,211,153,0.1);\n  }\n  .hidden { display: none !important; }\n\n  main { max-width: 940px; margin: 0 auto; padding: 24px 24px 120px; position: relative; z-index: 1; }\n\n  .step {\n    background: var(--card); border: 1px solid var(--border); border-radius: 16px;\n    padding: 30px 32px; margin-bottom: 24px;\n    opacity: 0; transform: translateY(22px); transition: opacity 0.6s ease, transform 0.6s ease;\n  }\n  .step.visible { opacity: 1; transform: translateY(0); }\n\n  .step h2 { font-size: 22px; margin-bottom: 10px; letter-spacing: -0.01em; }\n  .step h2 .num {\n    font-family: var(--display); color: var(--sd); font-size: 17px;\n    border: 1px solid rgba(163,230,53,0.35); border-radius: 8px; padding: 1px 8px; margin-right: 10px;\n  }\n  .step h3 { font-size: 15px; margin: 18px 0 8px; color: var(--text); }\n  .lead { color: var(--dim); font-size: 14px; margin-bottom: 14px; }\n\n  code, .mono {\n    font-family: var(--mono); font-size: 0.92em;\n    background: var(--raise); border: 1px solid var(--border); border-radius: 5px;\n    padding: 1px 6px; color: #ecfccb;\n  }\n  pre {\n    font-family: var(--mono); font-size: 12.5px; line-height: 1.6;\n    background: #0b0e14; border: 1px solid var(--border); border-radius: 10px;\n    padding: 14px 16px; overflow-x: auto; color: #ecfccb; margin: 12px 0;\n  }\n  pre .cmt { color: var(--muted); }\n  pre .key { color: #f0a04b; }\n  pre .val { color: #34d399; }\n\n  table { width: 100%; border-collapse: collapse; margin: 12px 0; font-size: 13px; }\n  th, td { border: 1px solid var(--border); padding: 8px 12px; text-align: left; }\n  th { background: var(--raise); color: var(--dim); font-size: 11.5px; letter-spacing: 0.5px; }\n  td code { border: none; background: transparent; padding: 0; }\n\n  .insight {\n    background: rgba(163,230,53,0.06); border: 1px solid rgba(163,230,53,0.25);\n    border-radius: 10px; padding: 14px 16px; font-size: 13px; color: var(--dim); margin: 12px 0;\n  }\n  .insight strong { color: var(--sd); }\n\n  .opts { display: grid; gap: 8px; margin: 12px 0; }\n  .opt-row {\n    display: flex; align-items: center; gap: 10px;\n    border: 1px solid var(--border); border-radius: 10px; padding: 11px 14px;\n    cursor: pointer; font-size: 13.5px; transition: border-color 0.2s, background 0.2s;\n    background: var(--raise);\n  }\n  .opt-row:hover { border-color: var(--line); }\n  .opt-row input { accent-color: var(--sd); }\n  .opt-row.correct { border-color: rgba(52,211,153,0.6); background: rgba(52,211,153,0.08); }\n  .opt-row.wrong { border-color: rgba(239,71,111,0.6); background: rgba(239,71,111,0.08); }\n  .opt-row.disabled { pointer-events: none; opacity: 0.55; }\n  .opt-row.disabled.correct { opacity: 1; }\n\n  .result { display: none; margin-top: 12px; font-size: 13px; border-radius: 10px; padding: 12px 14px; }\n  .result.show { display: block; }\n  .result.ok { background: rgba(52,211,153,0.08); border: 1px solid rgba(52,211,153,0.35); color: #a7f3d0; }\n  .result.err { background: rgba(239,71,111,0.08); border: 1px solid rgba(239,71,111,0.35); color: #fecdd3; }\n\n  .clab {\n    border: 1px solid var(--border); border-radius: 12px; overflow: hidden; margin: 14px 0;\n    background: #0b0e14;\n  }\n  .clab-head {\n    display: flex; align-items: center; gap: 6px; padding: 8px 14px;\n    background: var(--raise); border-bottom: 1px solid var(--border);\n    font-family: var(--mono); font-size: 11px; color: var(--muted);\n  }\n  .clab-head .dot { width: 9px; height: 9px; border-radius: 999px; background: #333b4a; }\n  .clab-head .dot:nth-child(1) { background: #ef476f; }\n  .clab-head .dot:nth-child(2) { background: #f0a04b; }\n  .clab-head .dot:nth-child(3) { background: #34d399; }\n  .clab-head span.txt { margin-left: 6px; }\n  .clab-body { padding: 12px 14px; }\n  .clab-body input {\n    width: 100%;\n    background: var(--raise); border: 1px solid var(--border); border-radius: 10px;\n    color: #ecfccb; font-family: var(--mono); font-size: 12.5px; line-height: 1.7;\n    padding: 12px; outline: none;\n  }\n  .clab-body input:focus { border-color: rgba(163,230,53,0.5); }\n  .clab-ctrl { display: flex; gap: 8px; padding: 10px 14px; border-top: 1px solid var(--border); flex-wrap: wrap; align-items: center; }\n  .clab-ctrl button {\n    background: var(--sd); border: 1px solid var(--sd); border-radius: 8px;\n    color: #101a05; font-family: var(--mono); font-size: 12px; font-weight: 700;\n    padding: 8px 16px; cursor: pointer; transition: opacity 0.2s;\n  }\n  .clab-ctrl button:hover { opacity: 0.88; }\n  .clab-ctrl .clab-hint { font-size: 11px; color: var(--muted); font-family: var(--mono); }\n  .clab-out {\n    border-top: 1px solid var(--border); padding: 12px 14px;\n    font-family: var(--mono); font-size: 12px; line-height: 1.7;\n    max-height: 240px; overflow-y: auto; white-space: pre-wrap; word-break: break-all;\n    color: #b8c2dd;\n  }\n  .clab-out .c-ok { color: #34d399; }\n  .clab-out .c-err { color: #ef476f; }\n  .clab-out .c-warn { color: #f0a04b; }\n  .clab-out .c-cmd { color: #a3e635; }\n\n  .quiz-box { margin-top: 8px; }\n  .quiz-q { margin-bottom: 20px; }\n  .q-title { font-size: 14.5px; margin-bottom: 8px; }\n  .q-title .q-num {\n    font-family: var(--mono); font-size: 11px; color: var(--sd);\n    border: 1px solid rgba(163,230,53,0.4); border-radius: 6px; padding: 1px 7px; margin-right: 8px;\n  }\n  .quiz-score {\n    background: rgba(163,230,53,0.06); border: 1px solid rgba(163,230,53,0.35);\n    border-radius: 12px; padding: 18px; text-align: center; margin-top: 8px;\n  }\n  .score-num-big { font-family: var(--display); font-size: 40px; color: var(--sd); }\n  .quiz-score p { color: var(--dim); font-size: 13px; margin-top: 4px; }\n\n  .nav {\n    position: fixed; bottom: 0; left: 0; right: 0; z-index: 60;\n    background: rgba(12,14,18,0.92); backdrop-filter: blur(10px);\n    border-top: 1px solid var(--border);\n  }\n  .nav-inner { max-width: 940px; margin: 0 auto; display: flex; align-items: center; justify-content: space-between; padding: 12px 24px; }\n  .nav-btn {\n    display: inline-flex; align-items: center; gap: 8px;\n    background: var(--raise); border: 1px solid var(--border); border-radius: 999px;\n    color: var(--text); font-family: var(--body); font-size: 13px; font-weight: 600;\n    padding: 9px 18px; cursor: pointer; transition: border-color 0.2s, color 0.2s;\n  }\n  .nav-btn:hover { border-color: var(--sd); color: var(--sd); }\n  .nav-btn svg { width: 15px; height: 15px; }\n  .hidden-nav { visibility: hidden; }\n  .nav-label { font-family: var(--mono); font-size: 12px; color: var(--muted); }\n\n  .toast {\n    position: fixed; bottom: 76px; left: 50%; transform: translateX(-50%) translateY(20px);\n    background: var(--raise); border: 1px solid rgba(52,211,153,0.5); color: #a7f3d0;\n    font-size: 13px; padding: 10px 18px; border-radius: 999px; z-index: 70;\n    opacity: 0; pointer-events: none; transition: opacity 0.25s, transform 0.25s;\n  }\n  .toast.show { opacity: 1; transform: translateX(-50%) translateY(0); }\n\n  .footer {\n    text-align: center; font-size: 10px; color: var(--muted);\n    letter-spacing: 1px; padding: 4px 24px 96px;\n  }\n\n  @media (max-width: 640px) {\n    .step { padding: 22px 18px; }\n    main { padding-left: 14px; padding-right: 14px; }\n  }\n\n  ",
  html: "\n\n\n<main>\n  <section class=\"mast\">\n    <div class=\"mast-top\">\n      <span class=\"badge\">DevOps</span>\n      <span class=\"mast-count\" id=\"stepLabel\">1 / 9</span>\n    </div>\n    <h1>Systemd <em>\u670d\u52a1\u7ba1\u7406</em></h1>\n    <p class=\"subtitle\">\u8ff7\u4f60 systemctl \u547d\u4ee4\u53f0 \u00b7 unit \u6587\u4ef6 \u00b7 \u6545\u969c\u6392\u67e5 \u00b7 9 \u4e2a\u91cc\u7a0b\u7891 \u00b7 \u8fdb\u5ea6\u81ea\u52a8\u4fdd\u5b58</p>\n    <div class=\"progress-track\"><div class=\"progress-fill\" id=\"progress\"></div></div>\n    <div class=\"progress-meta\">\n      <span id=\"progressLabel\">0 / 9 \u91cc\u7a0b\u7891</span>\n      <span class=\"done-badge hidden\" id=\"doneBadge\">\u2713 \u5df2\u5b8c\u6210</span>\n    </div>\n  </section>\n\n  <!-- \u2550\u2550\u2550 1 systemd \u662f\u4ec0\u4e48 \u2550\u2550\u2550 -->\n  <section class=\"step\">\n    <h2><span class=\"num\">1</span>systemd\uff1a\u73b0\u4ee3 Linux \u7684\u670d\u52a1\u7ba1\u5bb6</h2>\n    <p class=\"lead\">systemd \u662f PID 1\uff08\u7b2c\u4e00\u4e2a\u8fdb\u7a0b\uff09\uff0c\u8d1f\u8d23\u542f\u52a8/\u76d1\u7763/\u505c\u6b62\u670d\u52a1\u3002<strong>unit</strong> \u662f\u7ba1\u7406\u5bf9\u8c61\uff08.service / .socket / .timer \u7b49\uff09\uff0c<code>systemctl</code> \u662f\u4e0e\u5b83\u5bf9\u8bdd\u7684\u547d\u4ee4\u3002\u670d\u52a1\u5b9a\u4e49\u5728 <code>/etc/systemd/system/</code> \u6216 <code>/usr/lib/systemd/system/</code>\u3002</p>\n    <pre>$ systemctl status nginx     <span class=\"cmt\"># \u67e5\u770b\u670d\u52a1\u72b6\u6001</span>\n$ systemctl start nginx      <span class=\"cmt\"># \u542f\u52a8</span>\n$ systemctl enable nginx     <span class=\"cmt\"># \u5f00\u673a\u81ea\u542f</span>\n$ journalctl -u nginx        <span class=\"cmt\"># \u67e5\u770b\u670d\u52a1\u65e5\u5fd7</span></pre>\n    <h3>\u7ec3\u4e60\uff1asystemd \u6982\u5ff5</h3>\n    <div class=\"opts\" id=\"sdOpts\">\n      <label class=\"opt-row\" data-id=\"a\"><input type=\"radio\" name=\"sd\">systemd \u662f PID 1\uff1bunit \u662f\u7ba1\u7406\u5bf9\u8c61\uff1bsystemctl \u662f\u7ba1\u7406\u547d\u4ee4</label>\n      <label class=\"opt-row\" data-id=\"b\"><input type=\"radio\" name=\"sd\">systemd \u53ea\u662f\u4e00\u4e2a\u65e5\u5fd7\u5de5\u5177</label>\n      <label class=\"opt-row\" data-id=\"c\"><input type=\"radio\" name=\"sd\">systemctl \u53ea\u80fd\u67e5\u770b\uff0c\u4e0d\u80fd\u542f\u505c\u670d\u52a1</label>\n    </div>\n    <div class=\"result\" id=\"sdResult\"></div>\n  </section>\n\n  <!-- \u2550\u2550\u2550 2 \u547d\u4ee4\u53f0 1 \u2550\u2550\u2550 -->\n  <section class=\"step\">\n    <h2><span class=\"num\">2</span>\u547d\u4ee4\u53f0\uff1a\u542f\u52a8\u670d\u52a1\u5e76\u786e\u8ba4\u72b6\u6001</h2>\n    <p class=\"lead\">\u5728\u8f93\u5165\u6846\u6572\u5165 systemctl \u547d\u4ee4\uff08\u4e00\u884c\u4e00\u6761\uff09\uff0c\u56de\u8f66\u540e\u70b9\u300c\u6267\u884c\u300d\u3002\u76ee\u6807\u670d\u52a1\uff1a<code>nginx</code>\u3002</p>\n    <div class=\"insight\"><strong>\u4efb\u52a1\uff1a</strong>\u2460 \u542f\u52a8 nginx\uff1b\u2461 \u67e5\u770b\u5b83\u7684\u72b6\u6001\u786e\u8ba4 <code>active (running)</code>\u3002<strong>\u4e24\u6761\u547d\u4ee4\u90fd\u6267\u884c\u6b63\u786e\u540e\u89e3\u9501\u91cc\u7a0b\u7891\u3002</strong></div>\n    <div class=\"clab\">\n      <div class=\"clab-head\"><span class=\"dot\"></span><span class=\"dot\"></span><span class=\"dot\"></span><span class=\"txt\">root@host:~# \u8ff7\u4f60 systemctl</span></div>\n      <div class=\"clab-body\">\n        <textarea id=\"s1Input\" rows=\"2\" placeholder=\"systemctl start nginx&#10;systemctl status nginx\" spellcheck=\"false\"></textarea>\n      </div>\n      <div class=\"clab-ctrl\">\n        <button type=\"button\" id=\"s1Btn\">\u6267\u884c</button>\n        <span class=\"clab-hint\">\u652f\u6301 start / stop / restart / status / enable / disable / daemon-reload / journalctl</span>\n      </div>\n      <div class=\"clab-out\" id=\"s1Out\">\u2014 \u8f93\u5165\u547d\u4ee4 \u2014</div>\n    </div>\n    <div class=\"result\" id=\"s1Result\"></div>\n  </section>\n\n  <!-- \u2550\u2550\u2550 3 unit \u6587\u4ef6 \u2550\u2550\u2550 -->\n  <section class=\"step\">\n    <h2><span class=\"num\">3</span>unit \u6587\u4ef6\uff1a\u670d\u52a1\u957f\u4ec0\u4e48\u6837</h2>\n    <p class=\"lead\">\u4e09\u4e2a section\uff1a<code>[Unit]</code>\uff08\u63cf\u8ff0\u4e0e\u4f9d\u8d56\uff09\u3001<code>[Service]</code>\uff08\u600e\u4e48\u8dd1\uff09\u3001<code>[Install]</code>\uff08\u600e\u4e48\u5f00\u673a\u81ea\u542f\uff09\u3002\u5173\u952e\u5b57\u6bb5\uff1a<code>ExecStart</code>\uff08\u542f\u52a8\u547d\u4ee4\uff09\u3001<code>Restart</code>\uff08\u9000\u51fa\u540e\u662f\u5426\u91cd\u542f\uff09\u3002</p>\n    <pre>[Unit]\nDescription=My web service\nAfter=network.target\n\n[Service]\nExecStart=/usr/local/bin/app --port 8080\nRestart=on-failure        <span class=\"cmt\"># \u5931\u8d25\u81ea\u52a8\u62c9\u8d77</span>\nEnvironmentFile=/etc/app.env\n\n[Install]\nWantedBy=multi-user.target   <span class=\"cmt\"># \u591a\u7528\u6237\u542f\u52a8\u7ea7\u522b</span></pre>\n    <h3>\u7ec3\u4e60\uff1aunit \u6587\u4ef6</h3>\n    <div class=\"opts\" id=\"unitOpts\">\n      <label class=\"opt-row\" data-id=\"a\"><input type=\"radio\" name=\"unit\">[Unit] \u63cf\u8ff0/\u4f9d\u8d56\uff1b[Service] \u7684 ExecStart \u662f\u542f\u52a8\u547d\u4ee4\u3001Restart=on-failure \u5931\u8d25\u91cd\u542f</label>\n      <label class=\"opt-row\" data-id=\"b\"><input type=\"radio\" name=\"unit\">ExecStart \u5199\u5728\u54ea\u91cc\u90fd\u53ef\u4ee5</label>\n      <label class=\"opt-row\" data-id=\"c\"><input type=\"radio\" name=\"unit\">Restart=always \u8868\u793a\u4ece\u4e0d\u91cd\u542f</label>\n    </div>\n    <div class=\"result\" id=\"unitResult\"></div>\n  </section>\n\n  <!-- \u2550\u2550\u2550 4 \u547d\u4ee4\u53f0 2 \u2550\u2550\u2550 -->\n  <section class=\"step\">\n    <h2><span class=\"num\">4</span>\u547d\u4ee4\u53f0\uff1a\u91cd\u65b0\u52a0\u8f7d\u5e76\u8bbe\u81ea\u542f</h2>\n    <p class=\"lead\">\u6539\u4e86 unit \u6587\u4ef6\u540e\u5fc5\u987b <code>daemon-reload</code> \u8ba9 systemd \u91cd\u65b0\u8bfb\u53d6\uff1b<code>enable</code> \u8bbe\u5f00\u673a\u81ea\u542f\u3002</p>\n    <div class=\"insight\"><strong>\u4efb\u52a1\uff1a</strong>\u2460 \u91cd\u65b0\u52a0\u8f7d systemd \u914d\u7f6e\uff1b\u2461 \u628a nginx \u8bbe\u4e3a\u5f00\u673a\u81ea\u542f\u3002<strong>\u5168\u90e8\u6b63\u786e\u540e\u89e3\u9501\u91cc\u7a0b\u7891\u3002</strong></div>\n    <div class=\"clab\">\n      <div class=\"clab-head\"><span class=\"dot\"></span><span class=\"dot\"></span><span class=\"dot\"></span><span class=\"txt\">root@host:~# \u8ff7\u4f60 systemctl</span></div>\n      <div class=\"clab-body\">\n        <textarea id=\"s2Input\" rows=\"2\" placeholder=\"systemctl daemon-reload&#10;systemctl enable nginx\" spellcheck=\"false\"></textarea>\n      </div>\n      <div class=\"clab-ctrl\">\n        <button type=\"button\" id=\"s2Btn\">\u6267\u884c</button>\n        <span class=\"clab-hint\">daemon-reload \u65e0\u670d\u52a1\u540d</span>\n      </div>\n      <div class=\"clab-out\" id=\"s2Out\">\u2014 \u8f93\u5165\u547d\u4ee4 \u2014</div>\n    </div>\n    <div class=\"result\" id=\"s2Result\"></div>\n  </section>\n\n  <!-- \u2550\u2550\u2550 5 \u72b6\u6001\u5224\u8bfb \u2550\u2550\u2550 -->\n  <section class=\"step\">\n    <h2><span class=\"num\">5</span>\u72b6\u6001\u5224\u8bfb\uff1aactive / inactive / failed</h2>\n    <p class=\"lead\"><code>Active: active (running)</code> = \u6b63\u5e38\u8fd0\u884c\uff1b<code>active (exited)</code> = \u4e00\u6b21\u6027\u4efb\u52a1\u5df2\u5b8c\u6210\uff1b<code>inactive</code> = \u5df2\u505c\u6b62\uff1b<code>failed</code> = \u542f\u52a8/\u8fd0\u884c\u5931\u8d25\u3002<code>Loaded: not-found</code> = \u6ca1\u6709\u8fd9\u4e2a unit\u3002\u7528 <code>is-active</code> / <code>is-enabled</code> \u5728\u811a\u672c\u91cc\u53d6\u72b6\u6001\u3002</p>\n    <pre>$ systemctl is-active nginx\nactive\n$ systemctl is-enabled nginx\nenabled</pre>\n    <h3>\u7ec3\u4e60\uff1a\u72b6\u6001\u5224\u8bfb</h3>\n    <div class=\"opts\" id=\"stOpts\">\n      <label class=\"opt-row\" data-id=\"a\"><input type=\"radio\" name=\"st\">failed \u8868\u793a\u542f\u52a8/\u8fd0\u884c\u5931\u8d25\uff0c\u8981\u67e5\u65e5\u5fd7\u5b9a\u4f4d\u539f\u56e0</label>\n      <label class=\"opt-row\" data-id=\"b\"><input type=\"radio\" name=\"st\">active (exited) \u8868\u793a\u8fd8\u5728\u524d\u53f0\u8fd0\u884c</label>\n      <label class=\"opt-row\" data-id=\"c\"><input type=\"radio\" name=\"st\">is-enabled \u4e0e\u5f00\u673a\u81ea\u542f\u65e0\u5173</label>\n    </div>\n    <div class=\"result\" id=\"stResult\"></div>\n  </section>\n\n  <!-- \u2550\u2550\u2550 6 \u547d\u4ee4\u53f0 3 \u2550\u2550\u2550 -->\n  <section class=\"step\">\n    <h2><span class=\"num\">6</span>\u547d\u4ee4\u53f0\uff1a\u67e5\u770b\u670d\u52a1\u65e5\u5fd7</h2>\n    <p class=\"lead\"><code>journalctl</code> \u662f\u65e5\u5fd7\u4e2d\u5fc3\uff1a<code>-u nginx</code> \u53ea\u770b nginx\u3001<code>-f</code> \u8ddf\u968f\u8f93\u51fa\u3001<code>-xe</code> \u663e\u793a\u6700\u8fd1\u9519\u8bef\u4e0e\u7cfb\u7edf\u63d0\u793a\u3002</p>\n    <div class=\"insight\"><strong>\u4efb\u52a1\uff1a</strong>\u67e5\u770b nginx \u7684\u65e5\u5fd7\uff08\u7528 <code>-u</code> \u6307\u5b9a\u670d\u52a1\uff09\u3002<strong>\u6b63\u786e\u540e\u89e3\u9501\u91cc\u7a0b\u7891\u3002</strong></div>\n    <div class=\"clab\">\n      <div class=\"clab-head\"><span class=\"dot\"></span><span class=\"dot\"></span><span class=\"dot\"></span><span class=\"txt\">root@host:~# \u8ff7\u4f60 systemctl</span></div>\n      <div class=\"clab-body\">\n        <textarea id=\"s3Input\" rows=\"2\" placeholder=\"journalctl -u nginx&#10;journalctl -xe\" spellcheck=\"false\"></textarea>\n      </div>\n      <div class=\"clab-ctrl\">\n        <button type=\"button\" id=\"s3Btn\">\u6267\u884c</button>\n        <span class=\"clab-hint\">journalctl -u \u670d\u52a1\u540d / -f / -xe</span>\n      </div>\n      <div class=\"clab-out\" id=\"s3Out\">\u2014 \u8f93\u5165\u547d\u4ee4 \u2014</div>\n    </div>\n    <div class=\"result\" id=\"s3Result\"></div>\n  </section>\n\n  <!-- \u2550\u2550\u2550 7 \u8fdb\u9636\u914d\u7f6e \u2550\u2550\u2550 -->\n  <section class=\"step\">\n    <h2><span class=\"num\">7</span>\u8fdb\u9636\u914d\u7f6e</h2>\n    <p class=\"lead\">\u751f\u4ea7\u5e38\u7528\uff1a<code>Restart=on-failure</code>\uff08\u975e\u96f6\u9000\u51fa\u81ea\u52a8\u91cd\u542f\uff09\u3001<code>EnvironmentFile</code>\uff08\u5916\u7f6e\u73af\u5883\u53d8\u91cf\uff0c\u4fbf\u4e8e\u90e8\u7f72\uff09\u3001<code>LimitNOFILE</code>\uff08\u8fdb\u7a0b\u6587\u4ef6\u53e5\u67c4\u4e0a\u9650\uff09\u3001<code>User/Group</code>\uff08\u964d\u6743\u8fd0\u884c\uff09\u3001<code>TimeoutStartSec</code>\uff08\u542f\u52a8\u8d85\u65f6\uff09\u3002</p>\n    <pre>[Service]\nExecStart=/usr/bin/node /srv/app/server.js\nUser=www-data                 <span class=\"cmt\"># \u4e0d\u7528 root \u8dd1\u670d\u52a1</span>\nRestart=on-failure\nRestartSec=3\nEnvironmentFile=/srv/app/.env\nLimitNOFILE=65535</pre>\n    <h3>\u7ec3\u4e60\uff1a\u8fdb\u9636\u914d\u7f6e</h3>\n    <div class=\"opts\" id=\"advOpts\">\n      <label class=\"opt-row\" data-id=\"a\"><input type=\"radio\" name=\"adv\">User=www-data \u964d\u6743\u8fd0\u884c\uff1bEnvironmentFile \u5916\u7f6e\u73af\u5883\u53d8\u91cf\uff1bLimitNOFILE \u63d0\u9ad8\u53e5\u67c4\u4e0a\u9650</label>\n      <label class=\"opt-row\" data-id=\"b\"><input type=\"radio\" name=\"adv\">\u73af\u5883\u53d8\u91cf\u53ea\u80fd\u5199\u6b7b\u5728 unit \u6587\u4ef6\u91cc</label>\n      <label class=\"opt-row\" data-id=\"c\"><input type=\"radio\" name=\"adv\">RestartSec \u4e0e\u81ea\u52a8\u91cd\u542f\u65e0\u5173</label>\n    </div>\n    <div class=\"result\" id=\"advResult\"></div>\n  </section>\n\n  <!-- \u2550\u2550\u2550 8 \u547d\u4ee4\u53f0 4 \u2550\u2550\u2550 -->\n  <section class=\"step\">\n    <h2><span class=\"num\">8</span>\u547d\u4ee4\u53f0\uff1a\u6545\u969c\u6392\u67e5</h2>\n    <p class=\"lead\">\u670d\u52a1 failed \u65f6\u7684\u6807\u51c6\u6392\u67e5\uff1a\u5148 <code>status</code> \u770b\u72b6\u6001\u4e0e\u9000\u51fa\u7801\uff0c\u518d <code>journalctl -xe</code> \u770b\u9519\u8bef\u65e5\u5fd7\u3002</p>\n    <div class=\"insight\"><strong>\u4efb\u52a1\uff1a</strong>nginx \u542f\u52a8\u5931\u8d25\u4e86\u3002\u2460 \u67e5\u770b\u5b83\u7684\u72b6\u6001\uff08\u786e\u8ba4 failed\uff09\uff1b\u2461 \u7528 journalctl \u67e5\u770b\u6700\u8fd1\u9519\u8bef\u8be6\u60c5\u3002<strong>\u5168\u90e8\u6b63\u786e\u540e\u89e3\u9501\u91cc\u7a0b\u7891\u3002</strong></div>\n    <div class=\"clab\">\n      <div class=\"clab-head\"><span class=\"dot\"></span><span class=\"dot\"></span><span class=\"dot\"></span><span class=\"txt\">root@host:~# \u8ff7\u4f60 systemctl</span></div>\n      <div class=\"clab-body\">\n        <textarea id=\"s4Input\" rows=\"2\" placeholder=\"systemctl status nginx&#10;journalctl -xe\" spellcheck=\"false\"></textarea>\n      </div>\n      <div class=\"clab-ctrl\">\n        <button type=\"button\" id=\"s4Btn\">\u6267\u884c</button>\n        <span class=\"clab-hint\">status / journalctl -xe</span>\n      </div>\n      <div class=\"clab-out\" id=\"s4Out\">\u2014 \u8f93\u5165\u547d\u4ee4 \u2014</div>\n    </div>\n    <div class=\"result\" id=\"s4Result\"></div>\n  </section>\n\n  <!-- \u2550\u2550\u2550 9 \u638c\u63e1\u5ea6\u6d4b\u9a8c \u2550\u2550\u2550 -->\n  <section class=\"step\">\n    <h2><span class=\"num\">9</span>\u638c\u63e1\u5ea6\u6d4b\u9a8c</h2>\n    <p class=\"lead\">8 \u9053\u9898\uff0c\u7b54\u5bf9 6 \u9898\u4ee5\u4e0a\u89e3\u9501\"\u5b8c\u6210\"\u5fbd\u7ae0\u3002\u7b54\u9898\u5373\u65f6\u5224\u5206\uff0c\u5168\u90e8\u7b54\u5b8c\u4fdd\u5b58\u8fdb\u5ea6\u3002</p>\n    <div class=\"quiz-box\" id=\"quizBox\"></div>\n  </section>\n\n  <!-- \u2550\u2550\u2550 \u4e0b\u4e00\u6b65 \u2550\u2550\u2550 -->\n  <section class=\"step\">\n    <h2><span class=\"num\">\u2713</span>\u4e0b\u4e00\u6b65</h2>\n    <p class=\"lead\">\u4f60\u5df2\u7ecf\u8d70\u5b8c\uff1a\u6982\u5ff5 \u2192 \u542f\u505c\u4e0e\u72b6\u6001 \u2192 unit \u6587\u4ef6 \u2192 \u91cd\u8f7d\u4e0e\u81ea\u542f \u2192 \u72b6\u6001\u5224\u8bfb \u2192 \u65e5\u5fd7 \u2192 \u8fdb\u9636\u914d\u7f6e \u2192 \u6545\u969c\u6392\u67e5 \u2192 \u6d4b\u9a8c\u3002</p>\n    <div class=\"insight\">\n      <strong>\u5efa\u8bae\u7684\u5b9e\u6218\u8def\u7ebf\uff1a</strong><br>\n      \u2460 \u4e3a\u81ea\u5df1\u5199\u7684\u811a\u672c\u5199\u4e00\u4e2a .service \u653e\u5230 <code>/etc/systemd/system/</code>\uff0c<code>daemon-reload</code> \u540e\u542f\u7528\uff1b<br>\n      \u2461 \u7ed9\u5173\u952e\u670d\u52a1\u914d <code>Restart=on-failure</code> + <code>LimitNOFILE</code>\uff0c\u6a21\u62df\u5d29\u6e83\u89c2\u5bdf\u81ea\u52a8\u62c9\u8d77\uff1b<br>\n      \u2462 \u51fa\u95ee\u9898\u5148 <code>status</code> \u518d <code>journalctl -xe</code>\uff0c\u517b\u6210\u6392\u67e5\u4e60\u60ef\uff1b<br>\n      \u2463 \u7528 <code>systemctl list-units --type=service --state=failed</code> \u5de1\u68c0\u5168\u673a\u5931\u8d25\u670d\u52a1\u3002\n    </div>\n    <p class=\"lead\">\u56de\u5230 <a href=\"#/\" style=\"color:var(--accent)\">\u4ea4\u4e92\u5f0f\u5b66\u4e60\u5e93\u5bfc\u822a\u9875</a>\uff0c\u7ee7\u7eed\u5b66\u4e60\u5176\u4ed6\u4e13\u9898\u3002</p>\n  </section>\n</main>\n\n<!-- \u2550\u2550\u2550 BOTTOM NAV \u2550\u2550\u2550 -->\n<nav class=\"nav\">\n  <div class=\"nav-inner\">\n    <button class=\"nav-btn hidden-nav\" id=\"navPrev\">\n      <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><path d=\"M19 12H5M12 19l-7-7 7-7\"/></svg>\n      \u4e0a\u4e00\u8282\n    </button>\n    <span class=\"nav-label\" id=\"navLabel\">1 / 9</span>\n    <button class=\"nav-btn\" id=\"navNext\">\n      \u4e0b\u4e00\u8282\n      <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\"><path d=\"M5 12h14M12 5l7 7-7 7\"/></svg>\n    </button>\n  </div>\n</nav>\n\n<div class=\"toast\" id=\"toast\"></div>\n<div class=\"footer\">SYSTEMD \u670d\u52a1\u7ba1\u7406 \u4ea4\u4e92\u5f0f\u5b66\u4e60 \u00b7 9 \u4e2a\u91cc\u7a0b\u7891 \u00b7 \u8fdb\u5ea6\u81ea\u52a8\u4fdd\u5b58\u5728\u672c\u6d4f\u89c8\u5668</div>\n\n\n\n  \n",
  js: "\n\n(function () {\n  'use strict';\n\n  function $(id) { return document.getElementById(id); }\n  function esc(s) { var d = document.createElement('div'); d.textContent = String(s); return d.innerHTML; }\n  var toastTimer = null;\n  function toast(msg) {\n    var t = $('toast');\n    t.textContent = msg;\n    t.classList.add('show');\n    clearTimeout(toastTimer);\n    toastTimer = setTimeout(function () { t.classList.remove('show'); }, 2200);\n  }\n\n  /* \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 step nav \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 */\n  var steps = document.querySelectorAll('.step');\n  var totalSteps = steps.length;\n  var currentStep = 0;\n  var navPrev = $('navPrev'), navNext = $('navNext'), navLabel = $('navLabel');\n\n  function showNav() {\n    navPrev.classList.toggle('hidden-nav', currentStep === 0);\n    navNext.classList.toggle('hidden-nav', currentStep === totalSteps - 1);\n    navLabel.textContent = (currentStep + 1) + ' / ' + totalSteps;\n    $('stepLabel').textContent = (currentStep + 1) + ' / ' + totalSteps;\n  }\n  function scrollToStep(i) {\n    if (i < 0 || i >= totalSteps) return;\n    currentStep = i; showNav();\n    steps[i].scrollIntoView({ behavior: 'smooth', block: 'start' });\n  }\n  navPrev.addEventListener('click', function () { scrollToStep(currentStep - 1); });\n  navNext.addEventListener('click', function () { scrollToStep(currentStep + 1); });\n  var spyTimer;\n  window.addEventListener('scroll', function () {\n    clearTimeout(spyTimer);\n    spyTimer = setTimeout(function () {\n      var mid = window.scrollY + window.innerHeight * 0.4;\n      for (var i = 0; i < steps.length; i++) { if (steps[i].offsetTop <= mid) currentStep = i; }\n      showNav();\n    }, 60);\n  });\n  document.addEventListener('keydown', function (e) {\n    if (e.key === 'ArrowRight' || e.key === 'ArrowDown') { e.preventDefault(); scrollToStep(currentStep + 1); }\n    if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') { e.preventDefault(); scrollToStep(currentStep - 1); }\n  });\n\n  /* \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 reveal \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 */\n  var revealEls = document.querySelectorAll('.step');\n  if ('IntersectionObserver' in window) {\n    var observer = new IntersectionObserver(function (entries) {\n      entries.forEach(function (e) { if (e.isIntersecting) { e.target.classList.add('visible'); observer.unobserve(e.target); } });\n    }, { threshold: 0.1 });\n    revealEls.forEach(function (el) { observer.observe(el); });\n  } else {\n    revealEls.forEach(function (el) { el.classList.add('visible'); });\n  }\n\n  /* \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 progress + localStorage \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 */\n  var MODULE_KEY = 'systemd';\n  var TOTAL_MILESTONES = 9;\n  /* milestone indices:\n     0 systemd \u6982\u5ff5\u6b63\u786e\n     1 \u547d\u4ee4\u53f0 1\uff08start + status\uff09\u901a\u8fc7\n     2 unit \u6587\u4ef6\u6b63\u786e\n     3 \u547d\u4ee4\u53f0 2\uff08daemon-reload + enable\uff09\u901a\u8fc7\n     4 \u72b6\u6001\u5224\u8bfb\u6b63\u786e\n     5 \u547d\u4ee4\u53f0 3\uff08journalctl -u\uff09\u901a\u8fc7\n     6 \u8fdb\u9636\u914d\u7f6e\u6b63\u786e\n     7 \u547d\u4ee4\u53f0 4\uff08status + journalctl -xe\uff09\u901a\u8fc7\n     8 \u6d4b\u9a8c \u2265 6/8 */\n  var milestones = [false, false, false, false, false, false, false, false, false];\n\n  function loadProgress() {\n    try {\n      var store = JSON.parse(localStorage.getItem('il_progress') || '{}');\n      var g = store[MODULE_KEY];\n      if (!g || !g.steps) return;\n      g.steps.forEach(function (i) { if (i >= 0 && i < TOTAL_MILESTONES) milestones[i] = true; });\n      if (g.quiz && g.quiz.total) {\n        var qb = $('quizBox');\n        if (qb && qb.querySelector('.quiz-score') === null) {\n          var d = document.createElement('div');\n          d.className = 'quiz-score';\n          d.innerHTML = '<div class=\"score-num-big\">' + g.quiz.score + '/' + g.quiz.total + '</div><p>\u4e0a\u6b21\u6d4b\u9a8c\u6210\u7ee9\u5df2\u4ece\u672c\u5730\u8fdb\u5ea6\u6062\u590d</p>';\n          qb.appendChild(d);\n        }\n      }\n      if (g.done) $('doneBadge').classList.remove('hidden');\n      refreshProgress();\n    } catch (e) { /* storage unavailable */ }\n  }\n\n  function saveProgress() {\n    var doneCount = 0, i;\n    for (i = 0; i < TOTAL_MILESTONES; i++) if (milestones[i]) doneCount++;\n    try {\n      var store = JSON.parse(localStorage.getItem('il_progress') || '{}');\n      var g = store[MODULE_KEY] || {};\n      var stepsList = [];\n      for (i = 0; i < TOTAL_MILESTONES; i++) if (milestones[i]) stepsList.push(i);\n      g.steps = stepsList;\n      g.last = Date.now();\n      g.done = doneCount === TOTAL_MILESTONES;\n      store[MODULE_KEY] = g;\n      localStorage.setItem('il_progress', JSON.stringify(store));\n    } catch (e) { /* storage unavailable */ }\n  }\n\n  function refreshProgress() {\n    var doneCount = 0, i;\n    for (i = 0; i < TOTAL_MILESTONES; i++) if (milestones[i]) doneCount++;\n    var pct = Math.round(doneCount / TOTAL_MILESTONES * 100);\n    $('progress').style.width = pct + '%';\n    $('progressLabel').textContent = doneCount + ' / ' + TOTAL_MILESTONES + ' \u91cc\u7a0b\u7891';\n    if (doneCount === TOTAL_MILESTONES) $('doneBadge').classList.remove('hidden');\n    else $('doneBadge').classList.add('hidden');\n  }\n\n  function completeMilestone(i) {\n    if (i < 0 || i >= TOTAL_MILESTONES) return;\n    if (milestones[i]) return;\n    milestones[i] = true;\n    refreshProgress();\n    saveProgress();\n    toast('\u2713 \u91cc\u7a0b\u7891 ' + (i + 1) + ' / ' + TOTAL_MILESTONES + ' \u89e3\u9501');\n  }\n\n  /* \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 \u9009\u62e9\u9898\u7ed1\u5b9a\uff08label\u2192input \u5192\u6ce1\u9632\u91cd\u5165\uff09 \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 */\n  function bindOpts(elId, rightId, resultId, rightMsg, wrongMsg, milestoneIdx) {\n    $(elId).querySelectorAll('.opt-row').forEach(function (row) {\n      row.addEventListener('click', function () {\n        if (row.classList.contains('disabled')) return;\n        var rows = $(elId).querySelectorAll('.opt-row');\n        rows.forEach(function (r) { r.classList.remove('correct', 'wrong', 'disabled'); });\n        var selected = row.dataset.id;\n        rows.forEach(function (r) { r.classList.add('disabled'); });\n        var radio = row.querySelector('input'); radio.checked = true;\n        if (selected === rightId) {\n          row.classList.add('correct');\n          $(resultId).className = 'result show ok';\n          $(resultId).innerHTML = rightMsg;\n          if (milestoneIdx >= 0) completeMilestone(milestoneIdx);\n        } else {\n          row.classList.add('wrong');\n          $(resultId).className = 'result show err';\n          $(resultId).innerHTML = wrongMsg;\n        }\n      });\n    });\n  }\n\n  bindOpts('sdOpts', 'a', 'sdResult',\n    '\u6b63\u786e\uff01systemd \u662f PID 1\uff1bunit \u662f\u7ba1\u7406\u5bf9\u8c61\uff08.service \u7b49\uff09\uff1bsystemctl \u662f\u7ba1\u7406\u547d\u4ee4\u3002',\n    '\u4e0d\u5bf9\u3002systemd \u662f\u521d\u59cb\u5316\u7cfb\u7edf\u4e0e\u670d\u52a1\u7ba1\u7406\u5668\uff0csystemctl \u80fd\u542f\u505c\u3001\u67e5\u770b\u3001\u914d\u7f6e\u670d\u52a1\u3002', 0);\n  bindOpts('unitOpts', 'a', 'unitResult',\n    '\u6b63\u786e\uff01[Unit] \u63cf\u8ff0/\u4f9d\u8d56\uff0c[Service] \u7684 ExecStart \u5b9a\u4e49\u542f\u52a8\u547d\u4ee4\uff0cRestart=on-failure \u5931\u8d25\u81ea\u52a8\u91cd\u542f\u3002',\n    '\u4e0d\u5bf9\u3002ExecStart \u5fc5\u987b\u5728 [Service] \u6bb5\uff1bRestart=always \u662f\u603b\u662f\u91cd\u542f\u3002', 2);\n  bindOpts('stOpts', 'a', 'stResult',\n    '\u6b63\u786e\uff01failed = \u542f\u52a8/\u8fd0\u884c\u5931\u8d25\uff0c\u7528 status + journalctl \u5b9a\u4f4d\uff1bactive (exited) \u662f\u4e00\u6b21\u6027\u4efb\u52a1\u5df2\u5b8c\u6210\u3002',\n    '\u4e0d\u5bf9\u3002active (exited) \u8868\u793a\u5df2\u5b8c\u6210\uff1bis-enabled \u6b63\u8868\u793a\u5f00\u673a\u81ea\u542f\u72b6\u6001\u3002', 4);\n  bindOpts('advOpts', 'a', 'advResult',\n    '\u6b63\u786e\uff01User \u964d\u6743\u3001EnvironmentFile \u5916\u7f6e\u53d8\u91cf\u3001LimitNOFILE \u63d0\u9ad8\u53e5\u67c4\u4e0a\u9650\u3001RestartSec \u63a7\u5236\u91cd\u542f\u95f4\u9694\u3002',\n    '\u4e0d\u5bf9\u3002\u73af\u5883\u53d8\u91cf\u53ef\u4ee5\u5916\u7f6e\uff08EnvironmentFile\uff09\uff1bRestartSec \u662f\u81ea\u52a8\u91cd\u542f\u7684\u95f4\u9694\u3002', 6);\n\n  /* \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 \u8ff7\u4f60 systemctl \u547d\u4ee4\u53f0 \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 */\n  var SV = 'nginx';\n\n  function runSingle(line) {\n    line = line.trim();\n    if (!line) return { ok: true, html: '' };\n    if (/^journalctl/.test(line)) {\n      var parts = line.split(/\\s+/);\n      var hasU = parts.indexOf('-u') !== -1 || parts.indexOf('-f') !== -1 || parts.indexOf('-xe') !== -1 || parts.indexOf('--unit') !== -1;\n      if (!hasU) return { ok: false, html: '<span class=\"c-cmd\">$ ' + esc(line) + '</span>\\n<span class=\"c-err\">\u8bf7\u7528 -u \u6307\u5b9a\u670d\u52a1\uff08\u5982 journalctl -u ' + SV + '\uff09\u6216 -xe / -f</span>' };\n      if (parts.indexOf('-u') !== -1 && parts[parts.indexOf('-u') + 1] !== SV && parts.indexOf('-xe') === -1) {\n        return { ok: false, html: '<span class=\"c-cmd\">$ ' + esc(line) + '</span>\\n<span class=\"c-err\">No journal files for unit ' + esc(parts[parts.indexOf('-u') + 1] || '') + '.service</span>' };\n      }\n      return { ok: true, html: '<span class=\"c-cmd\">$ ' + esc(line) + '</span>\\n' + (parts.indexOf('-xe') !== -1 ? '-- Journal begins at ... --\\nOct 11 11:30:00 host systemd[1]: nginx.service: Failed with result exit-code.\\n<span class=\"c-err\">Oct 11 11:30:00 host nginx[456]: bind() to 0.0.0.0:80 failed (98: Address already in use)</span>\\nOct 11 11:30:00 host systemd[1]: nginx.service: Failed to start.\\n-- Defined-By: systemd --\\n-- A unit ... failed ... see systemctl status nginx.service --' : '-- Logs begin at ... --\\nOct 11 11:29:50 host systemd[1]: Starting nginx.service...\\nOct 11 11:29:50 host nginx[100]: nginx: configuration file /etc/nginx/nginx.conf test is successful\\nOct 11 11:29:50 host systemd[1]: Started nginx.service.\\n<span class=\"c-ok\">Oct 11 11:30:01 host nginx[101]: 10.0.0.1 GET / 200</span>') };\n    }\n    var m = line.match(/^systemctl\\s+([a-zA-Z-]+)\\s*(.*)$/) || line.match(/^([a-zA-Z-]+)\\s+(.+)$/);\n    if (m) {\n      var act = m[1], rest = (m[2] || '').trim();\n      var svc = rest.split(/\\s+/)[0] || '';\n      if (act === 'daemon-reload') {\n        return { ok: true, html: '<span class=\"c-cmd\">$ ' + esc(line) + '</span>\\nReloading systemd manager configuration...\\n\uff08\u6210\u529f\uff0c\u65e0\u8f93\u51fa\uff09' };\n      }\n      if (act === 'start') {\n        if (svc !== SV) return { ok: false, html: '<span class=\"c-cmd\">$ ' + esc(line) + '</span>\\n<span class=\"c-err\">Failed to start ' + esc(svc) + '.service: Unit not found.</span>' };\n        return { ok: true, html: '<span class=\"c-cmd\">$ ' + esc(line) + '</span>\\n\u25cf ' + SV + '.service - A high performance web server and a reverse proxy server\\n   Loaded: loaded (/usr/lib/systemd/system/' + SV + '.service; disabled; preset: disabled)\\n   Active: active (running) since 2026-10-11 11:30:01\\n Main PID: 123 (' + SV + ')' };\n      }\n      if (act === 'stop') {\n        return { ok: true, html: '<span class=\"c-cmd\">$ ' + esc(line) + '</span>\\n\u25cf ' + SV + '.service - A high performance web server and a reverse proxy server\\n   Active: inactive (dead)' };\n      }\n      if (act === 'restart') {\n        return { ok: true, html: '<span class=\"c-cmd\">$ ' + esc(line) + '</span>\\n\u25cf ' + SV + '.service - A high performance web server and a reverse proxy server\\n   Active: active (running) since 2026-10-11 11:31:02' };\n      }\n      if (act === 'status') {\n        if (svc !== SV) return { ok: false, html: '<span class=\"c-cmd\">$ ' + esc(line) + '</span>\\n<span class=\"c-err\">Unit ' + esc(svc) + '.service could not be found.</span>' };\n        return { ok: true, html: '<span class=\"c-cmd\">$ ' + esc(line) + '</span>\\n\u25cf ' + SV + '.service - A high performance web server and a reverse proxy server\\n   Loaded: loaded (/usr/lib/systemd/system/' + SV + '.service; enabled; preset: disabled)\\n   Active: <span class=\"c-ok\">active (running)</span> since 2026-10-11 11:30:01\\n Main PID: 123 (' + SV + ')\\n   Tasks: 3 (limit: 19095)' };\n      }\n      if (act === 'is-active') {\n        return { ok: true, html: '<span class=\"c-cmd\">$ ' + esc(line) + '</span>\\n<span class=\"c-ok\">active</span>' };\n      }\n      if (act === 'is-enabled') {\n        return { ok: true, html: '<span class=\"c-cmd\">$ ' + esc(line) + '</span>\\n<span class=\"c-ok\">enabled</span>' };\n      }\n      if (act === 'enable') {\n        return { ok: true, html: '<span class=\"c-cmd\">$ ' + esc(line) + '</span>\\nCreated symlink /etc/systemd/system/multi-user.target.wants/' + SV + '.service \u2192 /usr/lib/systemd/system/' + SV + '.service.' };\n      }\n      if (act === 'disable') {\n        return { ok: true, html: '<span class=\"c-cmd\">$ ' + esc(line) + '</span>\\nRemoved \"/etc/systemd/system/multi-user.target.wants/' + SV + '.service\".' };\n      }\n      return { ok: false, html: '<span class=\"c-cmd\">$ ' + esc(line) + '</span>\\n<span class=\"c-err\">Unknown systemctl action: ' + esc(act) + '</span>' };\n    }\n    return { ok: false, html: '<span class=\"c-cmd\">$ ' + esc(line) + '</span>\\n<span class=\"c-err\">Unknown command. \u8bd5\u8bd5 systemctl start ' + SV + ' / status ' + SV + ' / journalctl -u ' + SV + '</span>' };\n  }\n\n  function runLab(inputId, btnId, outId, resultId, accepted, milestoneIdx, taskName) {\n    $(btnId).addEventListener('click', function () {\n      var raw = $(inputId).value;\n      var lines = raw.split(/\\n/).filter(function (l) { return l.trim(); });\n      var out = $(outId);\n      var results = lines.map(runSingle);\n      var allOk = results.every(function (r) { return r.ok; });\n      out.innerHTML = results.map(function (r) { return r.html; }).join('\\n\\n');\n\n      /* \u89c4\u8303\u5316\u7528\u6237\u547d\u4ee4\u96c6 */\n      var got = [];\n      lines.forEach(function (l) {\n        l = l.trim();\n        if (/^systemctl/.test(l)) {\n          var p = l.split(/\\s+/);\n          var a = p[1] || '';\n          if (a === 'daemon-reload') got.push('daemon-reload');\n          else if (a && p[2]) got.push(a + ' ' + p[2]);\n        } else if (/^journalctl/.test(l)) {\n          var parts = l.split(/\\s+/);\n          var flag = parts.indexOf('-xe') !== -1 ? '-xe' : (parts.indexOf('-f') !== -1 ? '-f' : '-u');\n          var svc = parts[parts.indexOf('-u') + 1];\n          got.push(flag === '-u' ? 'journalctl ' + svc : 'journalctl ' + flag);\n        }\n      });\n      var missing = accepted.filter(function (a) {\n        return !got.some(function (g) {\n          if (a === 'status' || a === 'start' || a === 'enable' || a === 'disable' || a === 'restart' || a === 'stop') return g === a + ' ' + SV || g === a;\n          if (a === 'daemon-reload') return g === 'daemon-reload';\n          if (a === 'journal-u') return g.indexOf('journalctl') === 0 && g.indexOf(SV) !== -1;\n          if (a === 'journal-xe') return g === 'journalctl -xe';\n          return false;\n        });\n      });\n\n      if (!allOk) {\n        if (missing.length) out.innerHTML += '\\n\\n<span class=\"c-warn\">\u4ecd\u6709\u547d\u4ee4\u7f3a\u5931\uff1a' + esc(missing.join(' / ')) + '\uff0c\u8bf7\u8865\u5168\u540e\u91cd\u65b0\u6267\u884c\u3002</span>';\n        return;\n      }\n      if (missing.length === 0) {\n        completeMilestone(milestoneIdx);\n        $(resultId).className = 'result show ok';\n        $(resultId).innerHTML = taskName + '\u5b8c\u6210\uff01';\n        out.innerHTML += '\\n\\n<span class=\"c-ok\">\u2713 ' + esc(taskName) + '\u5168\u90e8\u6267\u884c\u6b63\u786e\uff0c\u91cc\u7a0b\u7891\u89e3\u9501\u3002</span>';\n      } else {\n        out.innerHTML += '\\n\\n<span class=\"c-warn\">\u8fd8\u5dee\uff1a' + esc(missing.join(' / ')) + '\uff0c\u8865\u5168\u540e\u91cd\u65b0\u6267\u884c\u3002</span>';\n      }\n    });\n  }\n\n  runLab('s1Input', 's1Btn', 's1Out', 's1Result', ['start', 'status'], 1, '\u542f\u52a8\u5e76\u786e\u8ba4\u72b6\u6001');\n  runLab('s2Input', 's2Btn', 's2Out', 's2Result', ['daemon-reload', 'enable'], 3, '\u91cd\u8f7d\u914d\u7f6e\u5e76\u8bbe\u81ea\u542f');\n  runLab('s3Input', 's3Btn', 's3Out', 's3Result', ['journal-u'], 5, '\u67e5\u770b\u65e5\u5fd7');\n  runLab('s4Input', 's4Btn', 's4Out', 's4Result', ['status', 'journal-xe'], 7, '\u6545\u969c\u6392\u67e5');\n\n  /* \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 \u638c\u63e1\u5ea6\u6d4b\u9a8c \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 */\n  var quizData = [\n    { q: 'systemd \u7684 PID \u662f\uff1f', opts: ['0', '1', '100', '1000'], right: 1, expl: 'systemd \u662f PID 1\uff0cLinux \u7b2c\u4e00\u4e2a\u7528\u6237\u8fdb\u7a0b\u3002' },\n    { q: '\u542f\u52a8\u670d\u52a1\u7684\u547d\u4ee4\u662f\uff1f', opts: ['systemctl enable', 'systemctl start', 'systemctl stop', 'systemctl reload'], right: 1, expl: 'start \u542f\u52a8\uff0cenable \u8bbe\u5f00\u673a\u81ea\u542f\u3002' },\n    { q: '\u8bbe\u7f6e\u5f00\u673a\u81ea\u542f\u7528\uff1f', opts: ['systemctl start', 'systemctl status', 'systemctl enable', 'journalctl'], right: 2, expl: 'enable \u521b\u5efa\u81ea\u542f\u7b26\u53f7\u94fe\u63a5\u3002' },\n    { q: '\u6539\u4e86 unit \u6587\u4ef6\u540e\u5fc5\u987b\u5148\uff1f', opts: ['systemctl daemon-reload', 'reboot', 'systemctl disable', 'systemctl is-active'], right: 0, expl: 'daemon-reload \u8ba9 systemd \u91cd\u65b0\u8bfb\u53d6\u914d\u7f6e\u3002' },\n    { q: '\u670d\u52a1\u542f\u52a8/\u8fd0\u884c\u5931\u8d25\uff0c\u72b6\u6001\u663e\u793a\uff1f', opts: ['active', 'failed', 'inactive', 'not-found'], right: 1, expl: 'failed = \u542f\u52a8\u6216\u8fd0\u884c\u5931\u8d25\u3002' },\n    { q: '\u67e5\u770b\u670d\u52a1\u65e5\u5fd7\u7528\uff1f', opts: ['systemctl status', 'journalctl -u nginx', 'dmesg', 'top'], right: 1, expl: 'journalctl \u662f\u65e5\u5fd7\u4e2d\u5fc3\uff0c-u \u6307\u5b9a\u670d\u52a1\u3002' },\n    { q: 'ExecStart \u5728 unit \u6587\u4ef6\u7684\u54ea\u4e2a\u6bb5\uff1f', opts: ['[Unit]', '[Install]', '[Service]', '[Timer]'], right: 2, expl: '[Service] \u5b9a\u4e49\u5982\u4f55\u8fd0\u884c\u670d\u52a1\u3002' },\n    { q: '\u670d\u52a1\u5d29\u6e83\u540e\u81ea\u52a8\u62c9\u8d77\uff0c\u914d\u7f6e\uff1f', opts: ['Restart=on-failure', 'Restart=never', 'Type=oneshot', 'WantedBy=multi-user.target'], right: 0, expl: 'on-failure\uff1a\u975e\u96f6\u9000\u51fa\u81ea\u52a8\u91cd\u542f\u3002' }\n  ];\n  var quizScore = 0, quizTotal = quizData.length, quizAnswered = 0;\n  var quizWrongs = [];\n\n  function renderQuiz() {\n    var box = $('quizBox');\n    /* wrongs-first: \u4e0a\u6b21\u9519\u9898\u4f18\u5148\u91cd\u505a (Round 13)\n     * quiz.wrongs \u5b58\u9898\u5e93\u7684\u539f\u59cb\u4e0b\u6807\uff08\u8bb0\u5728\u6bcf\u9898\u7684 _oi \u4e0a\uff09\uff0c\u91cd\u6392\u53ea\u6539\u53d8\u5448\u73b0\u987a\u5e8f\u3002\n     * Round 12 \u5b58\u7684\u662f\u5448\u73b0\u4e0b\u6807\uff0c\u4e8e\u662f\u7b2c\u4e8c\u6b21\u8fdb\u5165\u65f6\u62ff\"\u4e0a\u4e00\u8f6e\u91cd\u6392\u540e\u7684\u4f4d\u7f6e\"\u53bb\u5207\n     * \u8fd9\u4e00\u8f6e\u7684\u5168\u65b0\u6570\u7ec4\uff0c\u4f1a\u91cd\u505a\u4e00\u6279\u6839\u672c\u6ca1\u7b54\u9519\u7684\u9898\u3001\u5e76\u6f0f\u6389\u771f\u6b63\u7684\u9519\u9898\u3002 */\n    try {\n      var _pg = JSON.parse(localStorage.getItem('il_progress') || '{}')[MODULE_KEY];\n      quizData.forEach(function (item, oi) { item._oi = oi; });\n      if (_pg && _pg.quiz && _pg.quiz.wrongs && _pg.quiz.wrongs.length) {\n        var _want = {};\n        _pg.quiz.wrongs.forEach(function (oi) { _want[oi] = true; });\n        quizData.sort(function (a, b) {\n          return (_want[a._oi] ? 0 : 1) - (_want[b._oi] ? 0 : 1);\n        });\n      }\n    } catch (e) { /* storage unavailable */ }\n    var html = quizData.map(function (item, qi) {\n      var optsHtml = item.opts.map(function (o, oi) {\n        return '<label class=\"opt-row\" data-q=\"' + qi + '\" data-o=\"' + oi + '\"><input type=\"radio\" name=\"quizq' + qi + '\"><span>' + esc(o) + '</span></label>';\n      }).join('');\n      return '<div class=\"quiz-q\"><div class=\"q-title\"><span class=\"q-num\">Q' + (qi + 1) + '</span>' + esc(item.q) + '</div>' + optsHtml +\n        '<div class=\"result\" id=\"quizr' + qi + '\"></div></div>';\n    }).join('');\n    box.innerHTML = html;\n\n    box.querySelectorAll('.opt-row').forEach(function (row) {\n      row.addEventListener('click', function () {\n        if (row.classList.contains('disabled')) return;\n        var qi = parseInt(row.dataset.q, 10), oi = parseInt(row.dataset.o, 10);\n        var q = quizData[qi];\n        var rows = box.querySelectorAll('.opt-row[data-q=\"' + qi + '\"]');\n        rows.forEach(function (r) { r.classList.add('disabled'); r.classList.remove('correct', 'wrong'); });\n        var res = $('quizr' + qi);\n        row.querySelector('input').checked = true;\n        if (oi === q.right) {\n          row.classList.add('correct');\n          res.className = 'result show ok';\n          res.innerHTML = '\u2713 \u6b63\u786e\u3002' + esc(q.expl);\n          quizScore++;\n        } else {\n          rows[q.right].classList.add('correct');\n          row.classList.add('wrong');\n          quizWrongs.push(quizData[qi]._oi == null ? qi : quizData[qi]._oi);\n          res.className = 'result show err';\n          res.innerHTML = '\u2717 \u6b63\u786e\u7b54\u6848\uff1a' + esc(q.opts[q.right]) + '\u3002' + esc(q.expl);\n        }\n        quizAnswered++;\n        if (quizAnswered === quizTotal) finishQuiz();\n      });\n    });\n  }\n\n  function finishQuiz() {\n    var box = $('quizBox');\n    var old = box.querySelector('.quiz-score');\n    if (old) old.remove();\n    var d = document.createElement('div');\n    d.className = 'quiz-score';\n    d.innerHTML = '<div class=\"score-num-big\">' + quizScore + '/' + quizTotal + '</div>' +\n      '<p>' + (quizScore >= 6 ? '\u4f18\u79c0\uff01\u4f60\u5df2\u7ecf\u638c\u63e1 Systemd \u670d\u52a1\u7ba1\u7406\u7684\u6838\u5fc3\u64cd\u4f5c\u3002' : '\u7ee7\u7eed\u52a0\u6cb9\uff01\u56de\u770b\u4e0a\u9762\u7684\u7ae0\u8282\uff0c\u518d\u8bd5\u4e00\u6b21\u3002') + '</p>';\n    box.appendChild(d);\n    try {\n      var store = JSON.parse(localStorage.getItem('il_progress') || '{}');\n      var g = store[MODULE_KEY] || {};\n      g.quiz = { score: quizScore, total: quizTotal , wrongs: quizWrongs };\n      store[MODULE_KEY] = g;\n      localStorage.setItem('il_progress', JSON.stringify(store));\n    } catch (e) { /* storage unavailable */ }\n    if (quizScore >= 6) completeMilestone(8);\n  }\n\n  /* \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 init \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 */\n  loadProgress();\n  renderQuiz();\n  showNav();\n})();\n\n  ",
};